def card(key,name,start,execution,care,equipment=None,goal='Fortalecimento',url=None):
 tech={'posicao_inicial':[start],'execucao':execution,'pontos_chave':care+['Faça apenas o lado, apoio, amplitude e dose prescritos.'],'erros_comuns':['Usar impulso, forçar dor ou continuar após perder controlo.'],'dicas':['Respire normalmente. Peça ensino da técnica antes de treinar sozinho.']}
 cards[key]={'id':uid('exercise:'+key),'name':name,'locais':['Casa','Clínica'],'categoria':['Membro Inferior'],'equipamento':equipment or ['Sem equipamento'],'is_active':True,'created_by':'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','photo_url':url or base+key+'.png','video_url':None,'tecnica_info':tech,'tecnica_notas':'\n\n'.join(k.replace('_',' ')+'\n'+'\n'.join('• '+s for s in v) for k,v in tech.items()),'ajustes_maquina':[],'contextos_exercicio':['Reabilitação'],'objetivos_exercicio':[goal]}
