card('mobilidade','Tornozelo para cima e para baixo','Sentado ou deitado, apoie a perna e o calcanhar confortavelmente, deixando o pé livre para mexer.',['Mova lentamente o pé para cima e para baixo, sem forçar.','Uma subida e descida completas contam como uma repetição.'],['Não desenhe movimentos amplos para dentro nem force a ponta do pé.'],goal='Mobilidade / Alongamento')
card('sentado','Calcanhares e pontas dos pés sentado','Sente-se numa cadeira firme, joelhos dobrados e pés apoiados.',['Levante os calcanhares mantendo a parte da frente dos pés no chão e volte a apoiar.','Depois levante as pontas dos pés mantendo os calcanhares apoiados. O ciclo conta como uma repetição.'],['Sem carga adicional e numa amplitude confortável.'],goal='Mobilidade / Alongamento')
card('isometrico','Pressão suave do pé para fora — isométrico','Sentado, pé apoiado e orientado à frente. Encoste a parte externa da frente do pé a um apoio acolchoado, fixo e estável, colocado conforme ensinado.',['Pressione suavemente para fora, sem deixar o pé ou a perna mexer.','Mantenha durante o tempo prescrito e relaxe.'],['Não use um objeto solto que possa deslizar. A pressão não deve provocar dor aguda ou fricção na pele.'])
card('transferencia','Transferência de peso com apoio — tornozelo','De pé diante de uma bancada firme, mãos apoiadas e ambos os pés no chão.',['Transfira ligeiramente o peso entre os dois pés, aproximando-o do lado lesionado apenas dentro do apoio autorizado.','Regresse à distribuição inicial.'],['Não levantar o outro pé nem inclinar o tornozelo. Não fazer se não estiver autorizado a apoiar.'],goal='Propriocepção / Equilíbrio',url=gtps+'transferencia-peso.png')
card('marcha','Marcha em plano — recuperação do tornozelo','Use piso plano, livre de obstáculos, calçado estável e os auxiliares prescritos.',['Caminhe devagar, com passos curtos e controlados. Use canadianas se prescritas.','Pare para descansar antes de aumentar a claudicação.'],['A imagem mostra a variante sem canadianas; use-as se indicadas.','Só progrida tempo ou ritmo após tolerar a dose atual. Não é corrida.'],goal='Cardiovascular',url=gon+'marcha-curta.png')
card('ponte','Ponte glútea — recuperação do tornozelo','Deitado de costas, cabeça apoiada, joelhos dobrados e pés numa largura confortável.',['Eleve ligeiramente a bacia e volte a pousar devagar.'],['Faça apenas se o apoio dos pés for autorizado e confortável. Não compense arqueando a lombar.'],url=gtps+'ponte-bilateral.png')
card('dorsiflexao','Pé para cima com elástico — dorsiflexão','Sentado, perna e calcanhar apoiados, pé livre. Elástico à volta da frente do pé, preso num ponto fixo à sua frente, conforme ensinado.',['Puxe a ponta do pé na sua direção, contra o elástico.','Regresse lentamente, sem deixar o elástico puxar de forma brusca.'],['Fixação segura, elástico íntegro e resistência ligeira. Não prenda a objetos soltos.','O elástico puxa para a frente, não é segurado nas mãos; não rodar o joelho.'],['Elásticos'])
card('eversao','Pé para fora com elástico — eversão','Sentado, joelhos dobrados, calcanhares apoiados e elástico leve em laço à volta da frente dos dois pés, conforme ensinado.',['Mantenha o pé não exercitado estável. Mova a frente do outro pé ligeiramente para fora contra o elástico.','Regresse lentamente à posição inicial.'],['Mantenha o calcanhar e o joelho controlados, sem rodar toda a perna. Não force inversão no regresso.'],['Elásticos'])
card('gemeos','Elevação dos calcanhares com apoio — tornozelo','De pé no chão, diante de bancada firme, mãos apoiadas e pés paralelos.',['Eleve os dois calcanhares e volte a pousá-los devagar.'],['Não balance o corpo nem deixe o tornozelo ceder para fora.'],url=gon+'calcanhares.png')
card('parede','Joelho à parede — mobilidade do tornozelo','De pé diante de uma parede, mãos apoiadas e um pé perto da parede, com calcanhar no chão.',['Aproxime suavemente o joelho da parede, mantendo-o orientado sobre o pé.','Regresse. Não é necessário tocar na parede se isso exigir forçar.'],['Aproxime mais o pé da parede se necessário. Não levantar o calcanhar nem insistir numa dor de bloqueio.'],goal='Mobilidade / Alongamento')
card('equilibrio','Equilíbrio numa perna com apoio — tornozelo','De pé junto de uma bancada firme, apoie as mãos conforme necessário.',['Transfira o apoio para a perna selecionada e levante ligeiramente o outro pé.','Mantenha o tempo prescrito, com tornozelo e joelho controlados.'],['Olhos abertos e piso firme. Pode manter contacto das mãos; não é uma prova sem apoio.'],goal='Propriocepção / Equilíbrio',url=gtps+'apoio-unipodal.png')
card('cadeira','Sentar e levantar — recuperação do tornozelo','Cadeira firme, altura adaptada, pés apoiados e separados numa largura confortável.',['Levante-se e sente-se devagar, usando os braços se necessário.'],['Mantenha os pés apoiados. Use cadeira mais alta se o tornozelo não tolerar maior flexão.'],url=gtps+'sentar-levantar.png')
card('gemeos-unipodal','Elevação do calcanhar numa perna com apoio','De pé no chão, mãos apoiadas numa bancada firme, peso na perna selecionada e outro pé ligeiramente levantado.',['Eleve o calcanhar com controlo e volte ao chão devagar.'],['Se difícil, regresse à versão com dois pés. Não fazer na borda de um degrau nesta fase.'])
card('degrau','Subir e descer um degrau baixo com apoio — tornozelo','Junto de corrimão ou bancada firme, use um degrau baixo e estável.',['Suba com o pé selecionado, controlando o tornozelo e o joelho.','Regresse devagar à posição inicial, com o apoio necessário. Subir e regressar contam como uma repetição.'],['Não saltar nem aumentar a altura antes de controlar a versão baixa.'],url=gtps+'step-up.png')
card('inclinacao','Inclinação à frente numa perna com apoio','De pé junto de bancada firme, uma mão apoiada, peso na perna selecionada e joelho ligeiramente dobrado.',['Incline ligeiramente o tronco pela anca, levando a outra perna um pouco para trás.','Regresse com controlo.'],['Amplitude curta, sem peso adicional. Mantenha o pé de apoio estável; não é necessário baixar o tronco até ficar horizontal.'])
card('toques','Toques em três direções com apoio','De pé junto de uma bancada firme, mão apoiada e peso na perna selecionada.',['Toque ligeiramente com o outro pé à frente, ao lado e atrás, regressando ao centro entre toques.','Os três toques e regressos contam como um ciclo.'],['Alcances curtos, sem saltos. A perna de apoio permanece controlada e o pé de toque não sustenta o peso principal.'],goal='Propriocepção / Equilíbrio')
card('laterais','Passos laterais controlados junto da bancada','De pé ao longo de bancada firme, pés numa largura confortável, mãos próximas do apoio.',['Dê passos curtos para um lado e depois para o outro, sem cruzar os pés.'],['Sem elástico e sem saltar. Mantenha apoio disponível e espaço livre.'],goal='Propriocepção / Equilíbrio')
def dose(sets,n,rest=30,timed=False):
 return {'sets':sets,'load':None,'reps_min':None if timed else n,'reps_max':None if timed else n,'reps_fixed':None if timed else n,'series':None if timed else [{'reps':n,'load':None} for _ in range(sets)],'duration_sec':None,'duration_series':[{'duration_sec':n} for _ in range(sets)] if timed else None,'rest_set':rest,'rest_next':rest,'tempo_concentrico_s':None if timed else 2,'tempo_excentrico_s':None if timed else 3,'pausa_superior_s':0,'pausa_inferior_s':0}
