parts=['<!doctype html><html lang="pt-PT"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Entorse do tornozelo</title><style>body{font:17px/1.5 system-ui;color:#173655;background:#eff4f8}main{max-width:1100px;margin:auto;padding:20px}section,article{background:white;border-radius:14px;padding:20px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px}img{width:100%;height:230px;object-fit:contain}summary{font-weight:bold;cursor:pointer}button{background:#245bec;color:white;border:0;padding:12px;border-radius:8px}</style><main><h1>Entorse do tornozelo — plano domiciliário</h1><p>Pré-visualização da biblioteca. Só a seleção individual constitui prescrição.</p>']
