 n=p['phase_order'];parts.append('<section><h2>'+esc(p['name'])+'</h2><p>Progressão por critérios, sem semanas obrigatórias.</p><details id="r'+str(n)+'" '+('open' if n==1 else '')+'><summary>Precauções e recomendações</summary>')
